  screen('collection-place','collect','Collection · source & place','Where are you collecting?','The source apiary stays the same wherever you meet.',()=>`${source()}${choice('receivingPlace','apiary','At the apiary','Visiting the farmer’s hives.')}${choice('receivingPlace','centre','At a collection centre','The farmer brought the honey to us.')}${state.receivingPlace==='centre'?field('centre','Collection centre','Gulu collection centre',{choices:['Gulu collection centre','Northern collection centre'],required:true}):''}${button('Change farmer or apiary','find-farmer','text-action')}`,'collection-dates','Continue',{...stepExtra(1,6,'Honey collection'),back:'choose-apiary'});
  screen('collection-dates','collect','Collection · dates','When was it collected?','Collection and harvest may happen on different days.',()=>`${field('collectionDate','Collection date',state.collectionDate,{type:'date',required:true})}<h2>When was it harvested?</h2>${choice('harvest','exact','I know the exact date')}${choice('harvest','range','I know roughly when')}${choice('harvest','unknown','The harvest date is unknown')}${state.harvest==='exact'?field('harvestDate','Harvest date',state.harvestDate,{type:'date',required:true}):state.harvest==='range'?`<div class="field-grid">${field('harvestFrom','From',state.harvestFrom,{type:'date',required:true})}${field('harvestTo','To',state.harvestTo,{type:'date',required:true})}</div>`:''}`,'collection-weight','Continue',{...stepExtra(2,6,'Honey collection'),back:'collection-place',note:'Require collection date. Preserve exact, approximate and unknown harvest timing without relabelling collection as harvest.'});
  screen('collection-weight','collect','Collection · weight & grade','Weigh the honey','Weigh everything in this collection together.',()=>`${field('material','What are you receiving?','honey',{choices:['honey','honeycomb'],required:true})}<div class="field-grid">${field('gross','Filled weight',state.gross,{type:'number',inputmode:'decimal',unit:'kg',required:true})}${field('tare','Empty buckets',state.tare,{type:'number',inputmode:'decimal',unit:'kg',required:true})}</div>${amount('Honey weight',`<span data-calc="net">${net()}</span> <small>kg</small>`,'Filled weight minus empty buckets')}${field('grade','Receiving grade','Grade A · example',{choices:['Grade A · example','Grade B · example','Needs assessment'],required:true,hint:'Use the company’s agreed receiving grades.'})}`,'collection-payment','Continue',{...stepExtra(3,6,'Honey collection'),back:'collection-dates',note:'Grades here are sample labels pending operational definition. This is a receiving grade, not a certification or quality release.'});
  screen('collection-payment','collect','Collection · price & payment','Agree the price','Read the total back to the farmer.',()=>`${field('price','Price for each kg',state.price,{type:'number',inputmode:'decimal',unit:'UGX',required:true})}${amount('Total agreed',`UGX <span data-calc="total">${total()}</span>`,`${net()} kg × UGX ${money(state.price)} per kg`)}<h2>Has the farmer been paid?</h2>${choice('payment','unpaid','Not paid yet','Record the amount owed.')}${choice('payment','paid','Paid now','Add the actual payment details.')}${state.payment==='paid'?`${field('paidAmount','Amount paid',String(net()*Number(state.price)),{type:'number',inputmode:'decimal',unit:'UGX',required:true})}${field('paymentMethod','Payment method','Mobile money',{choices:['Mobile money','Cash'],required:true})}${field('paymentRef','Payment or receipt reference','',{required:true,placeholder:'Enter the transaction reference'})}`:''}`,'collection-buckets','Continue',{...stepExtra(4,6,'Honey collection'),back:'collection-weight',note:'An agreed price is not a payment. Actual amount, method and reference are needed when recording payment.'});
  screen('collection-buckets','collect','Collection · buckets','How is it packed?','Give each bucket its own weight and label.',()=>`${card(`<div class="card-title"><strong>Bucket 1</strong>${badge('HB-7K2M','neutral')}</div>${field('bucketOne','Honey in this bucket',state.bucketOne,{type:'number',inputmode:'decimal',unit:'kg',required:true})}`)}${card(`<div class="card-title"><strong>Bucket 2</strong>${badge('HB-7K2N','neutral')}</div>${field('bucketTwo','Honey in this bucket',state.bucketTwo,{type:'number',inputmode:'decimal',unit:'kg',required:true})}`)}${callout('Match the collection weight',`Together, the buckets must contain ${net()} kg.`)}`,'collection-review','Review collection',{...stepExtra(5,6,'Honey collection'),back:'collection-payment',note:'Two buckets demonstrate per-container allocation. The product must support adding/removing arbitrary buckets and allocate collision-safe codes offline.'});
  screen('collection-review','collect','Collection · review','Check before saving','Confirm the source, weight and price with the farmer.',()=>`${source()}${dates()}${summary([['Receiving place',state.receivingPlace==='centre'?'Gulu collection centre':'At the apiary'],['Material',esc(state.material)],['Net weight',`${net()} kg`],['Grade',esc(state.grade||'Grade A · example')],['Price per kg',`UGX ${money(state.price)}`],['Buckets',`2 · ${esc(state.bucketOne)} kg + ${esc(state.bucketTwo)} kg`],['Payment',state.payment==='paid'?`Paid · UGX ${money(state.paidAmount||net()*state.price)}`:'Not paid yet']])}${amount('Total agreed',`UGX ${total()}`)}${button('Change weight or price','collection-weight','text-action','edit')}`,'collection-saved','Save collection',{...stepExtra(6,6,'Honey collection'),back:'collection-buckets',note:'A review is not a save. Only show success after a durable local write or a confirmed server commit. Repeated taps must retain the same transaction.'});
