  screen('supervisor-pending','work','Supervisor review pending','A supervisor will review this','You can continue with other work.',()=>`${success(true)}${card('<h3>Grace A. · source details</h3><p class="small">We need to confirm whether two farmer records refer to the same person.</p>')}${callout('Linked records are waiting','The apiary, collection and existing bucket codes are preserved.','warning')}${row('View the waiting collection','COL-1042','collection-history','bucket')}`,'my-work','Back to My work',{note:'Officers cannot merge identities or reassign a committed source. Supervisor resolution has a separate example.'});
  screen('session-expired','work','Session expired','Sign in to sync','Your work is still on this phone.',()=>`${success(true)}${callout('2 collections waiting','Sign in to the same account when you have internet. Your saved work will stay here.','warning')}${card('<h3>Amina’s account</h3><p class="small">The approved offline session has ended. New capture will be available after sign-in.</p>')}`,'sign-in','Sign in again',{noNav:true,note:'This state shows expiry of offline authorization, not merely network loss. Apply the agreed session-age policy.'});
  screen('save-failed','work','Device save failed','This has not been saved','Your entries are still here. Keep this screen open.',()=>`${callout('This phone could not save the collection','Do not close the app or remove its stored data. Try again or ask for help.','error')}${source()}${summary([['Honey',`${net()} kg`],['Total agreed',`UGX ${total()}`]])}${row('Get help','Share the problem without losing the form','help','help')}`,'collection-review','Return to entries and retry',{note:'Never show “Saved” before durable storage completes. Preserve entries in the open form; do not advise clearing application data.'});
