  screen('hq-home','receive','Receiving home','Hello, Daniel','Let’s get today’s honey safely into stock.',()=>`${task('Receive a bucket','Scan or enter the code on the label','receive-code','bucket',true)}<h2>Next in your queue</h2>${row('2 buckets need source details','30 kg · stored separately','stock-list','search')}${row('1 bucket needs checks','15 kg · receiving bay','quality-checks','shield')}${row('View all stock','Weights, locations and status','stock-list','list')}${callout('Receive first, then check','Every confirmed arrival appears in stock immediately.')}`,null,null,{role:'receiving',nav:'home',header:'brand',note:'This home belongs to receiving staff. A separate quality-manager view controls release decisions.'});
  screen('receive-code','receive','Receive · bucket code','Read the bucket label','Scan the code or type it below.',()=>`<div class="scanner"><div class="scan-frame">${icon('scan')}</div><span class="scan-caption">Camera preview example</span></div>${button('Try an example scan','!scan','secondary','scan')}${field('arrivalCode','Bucket code','HB-7K2M',{required:true,placeholder:'For example HB-7K2M'})}${button('The label is damaged','damaged-label','text-action')}`,'receive-arrival','Find bucket',{role:'receiving',back:'hq-home',step:[1,3,'Receive honey'],note:'Camera actions are simulated in the reference. Always provide typing and damaged-label alternatives.'});
  screen('receive-arrival','receive','Receive · arrival details','Record the arrival','Record what actually arrived at HQ.',()=>`${badge(esc(state.arrivalCode),'neutral')}${callout('Source details have not arrived yet','You can still record the bucket into stock. Keep it separate.','warning')}${field('receivedWeight','Received net weight',state.receivedWeight,{type:'number',inputmode:'decimal',unit:'kg',required:true})}${field('storage','Storage location',state.storage,{choices:['Receiving bay · Shelf A','Receiving bay · Shelf B','Held stock · Shelf H'],required:true})}${field('condition','Bucket condition',state.condition,{choices:['Sealed, no visible damage','Seal damaged','Leak or visible damage'],required:true})}${field('arrivalTime','Arrival time','2026-10-27T11:20',{type:'datetime-local',required:true})}`,'receive-review','Review arrival',{role:'receiving',back:'receive-code',step:[2,3,'Receive honey']});
  screen('receive-review','receive','Receive · review','Check this arrival','This bucket will be stored while source details catch up.',()=>`${summary([['Bucket code',esc(state.arrivalCode)],['Net weight',`${esc(state.receivedWeight)} kg`],['Location',esc(state.storage)],['Condition',esc(state.condition)],['Source','Awaiting source details'],['Quality','Awaiting checks']])}${callout('Processing stays blocked','Source reconciliation and required quality release must both be complete.','warning')}${button('Check the code again','receive-code','text-action')}`,'arrival-saved','Save arrival',{role:'receiving',back:'receive-arrival',step:[3,3,'Receive honey'],note:'Online authorized commit. Count this physical arrival once; do not manufacture a farmer or a second purchase.'});
  screen('arrival-saved','receive','Arrival saved','Bucket is now in stock','Stored separately while details are completed.',()=>`${success()}${amount('Received at HQ',`${esc(state.receivedWeight)} kg`,esc(state.storage))}<div class="badges">${badge('Awaiting source details','warning')}${badge('Awaiting checks','neutral')}</div>${row('View this bucket','Arrival ARR-2081','stock-item','bucket')}${callout('You can record checks now','Honey cannot be processed until its source and quality are resolved.','info')}`,'quality-checks','Record quality checks',{role:'receiving',secondary:['Receive another bucket','receive-code'],note:'The original arrival is linked after source sync, never inserted again. Source resolution alone does not confer quality release.'});
