  function publicStory(mixed=false){return `<div class="public-hero"><span class="app-eyebrow">A LITTLE CLOSER TO THE SOURCE</span><h1>Good honey.<br>A story worth knowing.</h1><p>${mixed?'Two apiaries, one carefully recorded batch.':'From the shea trees of northern Uganda to your table.'}</p><div class="welcome-art" style="margin-bottom:0;height:115px">${landscape()}</div></div><div class="badges">${badge(mixed?'HB-261027-B':'HB-261027-A','neutral')}${badge(mixed?'2 source apiaries':'1 source apiary')}</div>`;}
  screen('public-lookup','public','Customer · enter code','Every jar has a story','Enter the batch code from the bottom of your jar.',()=>`<div class="welcome-art">${landscape()}</div>${field('publicCode','Batch code','HB-261027-A',{required:true,placeholder:'For example HB-261027-A'})}<details class="disclosure"><summary>Where is the code?</summary><p>Look for a short code beginning with HB on the jar’s batch label.</p></details><p class="small">Jars from the same batch share a code.</p>`,'!lookup','Find my honey',{role:'public',noNav:true,header:'brand',back:null,note:'This represents the other customer website. Public lookup returns an approved projection, never operational staff records.'});
  screen('public-batch','public','Customer · batch story','',null,()=>`${publicStory()}<h2>Meet Grace</h2><div class="photo-preview" style="height:200px">${portrait()}</div><p>Grace has kept bees for 20 years. Her hives sit among shea trees, where she tends them with knowledge passed through her family.</p>${row('Shea Grove apiary','Gulu area · northern Uganda','public-source','leaf')}<h2>From apiary to jar</h2>${timeline([['Harvested between 20–25 Oct 2026','Approximate dates reported at collection','leaf'],['Collected on 27 Oct 2026','Shea Grove apiary','bucket'],['Bottled on 27 Oct 2026','Batch HB-261027-A','jar']])}<p class="small">Farmer story and illustration shown as an example of approved public content.</p>`,'public-source','Explore the source',{role:'public',noNav:true,header:'brand',back:'public-lookup',note:'Photo placeholder is an original illustration, not a real farmer. In the product use only permissioned and approved assets. No private fields reach this page.'});
  screen('public-source','public','Customer · apiary & forage','Shea Grove apiary','Gulu area, northern Uganda',()=>`${map(true)}<p class="small">The map shows the general source area. The apiary’s exact position is private.</p><h2>Around the hives</h2><div class="forage-chips"><span>Shea trees</span><span>Seasonal wild flowers</span></div><p>The bees forage among shea trees and seasonal flowers around the apiary.</p>${summary([['Farmer','Grace'],['Collected on','27 Oct 2026'],['Harvested between','20–25 Oct 2026<br><span class="small">Approximate</span>']])}`,'public-batch','Back to the batch story',{role:'public',noNav:true,header:'brand',back:'public-batch',note:'This illustrative map encodes no private GPS. Production should request only approved coarse areas and provide the same text if the map cannot load.'});
  screen('public-blend','public','Customer · multiple sources','',null,()=>`${publicStory(true)}<h2>Two places, one batch</h2><p>This batch combines honey from two apiaries. Each source keeps its own collection and harvest dates.</p>${card('<h3>Shea Grove · Gulu area</h3>'+summary([['Collected on','27 Oct 2026'],['Harvested between','20–25 Oct 2026<br>Approximate'],['Forage','Shea trees']]))}${card('<h3>River apiary · northern Uganda</h3>'+summary([['Collected on','26 Oct 2026'],['Harvest timing','Harvest date not recorded'],['Forage','Coffee and wild flowers']]))}<p class="small">Bottled on 27 Oct 2026. Farmer profiles are shown only when approved.</p>`,'public-lookup','Look up another batch',{role:'public',noNav:true,header:'brand',back:'public-lookup',note:'Do not attribute a blend to one farmer or fabricate a single harvest date. This separate sample batch preserves both contributors.'});
  screen('public-no-profile','public','Customer · source summary','Honey from northern Uganda','Batch HB-261027-C',()=>`<div class="welcome-art">${landscape()}</div><h2>About this batch</h2><p>Honey collected from one apiary in the Gulu area.</p>${summary([['Collected on','27 Oct 2026'],['Harvest date','Not recorded'],['Bottled on','27 Oct 2026'],['Forage','Shea trees']])}${map(true)}<p class="small">This page shares the approved source information for your batch.</p>`,'public-lookup','Look up another batch',{role:'public',noNav:true,header:'brand',back:'public-lookup',note:'Valid page without a farmer photo or story. Approximate area is separately approved; omit it too if sharing is declined. Do not expose internal consent states.'});
  screen('public-not-found','public','Customer · no public batch','We couldn’t find that batch','Check the code on your jar and try again.',()=>`<div class="empty-state"><div class="success-mark warning">${icon('search')}</div><p>Make sure every letter and number matches the label.</p></div>${field('publicCode','Batch code','HB-261027-A',{required:true})}`,'!lookup','Try this code',{role:'public',noNav:true,header:'brand',back:'public-lookup',note:'Use the same neutral result for unknown and unpublished batches. Never disclose unpublished operational details.'});
  screen('public-unavailable','public','Customer · service unavailable','The story is taking a moment','We can’t load this batch right now. Please try again.',()=>`<div class="empty-state"><div class="success-mark warning">${icon('cloud')}</div></div>${callout('Keep the code handy','You can return using the code printed on your jar.','info')}`,'!lookup','Try again',{role:'public',noNav:true,header:'brand',back:'public-lookup',note:'A service outage must not be presented as an invalid batch. Retry the same code.'});
  screen('public-recalled','public','Customer · batch notice','Important batch notice','Batch HB-261027-A',()=>`${callout('Please do not use this honey','This batch is included in a recall.','error')}<p>Keep the jar and its batch label. Contact the company or the shop where you bought it for return instructions.</p>${summary([['Affected batch','HB-261027-A'],['Notice updated','28 Oct 2026']])}<details class="disclosure"><summary>Why am I seeing this notice?</summary><p>The approved response for this batch has changed. Follow the current instructions shown here.</p></details>`,'public-lookup','Check another batch',{role:'public',noNav:true,header:'brand',back:'public-lookup',note:'Example approved recall response only. Actual wording, contact channels and return procedure require the quality owner’s policy. Hide promotional story content while recalled.'});

